CREATE TABLE alias_claims ( id INTEGER NOT NULL, name_a VARCHAR(200) NOT NULL, key_a VARCHAR(200) NOT NULL, name_b VARCHAR(200) NOT NULL, key_b VARCHAR(200) NOT NULL, source VARCHAR(16) DEFAULT '' NOT NULL, edition_id INTEGER, apart BOOLEAN DEFAULT 0 NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE api_keys ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, name VARCHAR(100) NOT NULL, scope VARCHAR(8) NOT NULL, token_hash VARCHAR(64) NOT NULL, prefix VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, expires_at DATETIME, blocked_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE auth_sessions ( id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, account_id INTEGER NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, last_seen_at DATETIME NOT NULL, ip VARCHAR(64) NOT NULL, user_agent VARCHAR(255) NOT NULL, uid VARCHAR(32) DEFAULT '' NOT NULL, remember BOOLEAN DEFAULT 1 NOT NULL, stage VARCHAR(8) DEFAULT 'full' NOT NULL, second_factor_by_provider BOOLEAN DEFAULT 0 NOT NULL, PRIMARY KEY (id), UNIQUE (token_hash), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE auto_runs ( id INTEGER NOT NULL, kind VARCHAR(10) NOT NULL, started_at DATETIME NOT NULL, finished_at DATETIME, counts JSON, error VARCHAR(64) DEFAULT '' NOT NULL, PRIMARY KEY (id) );
CREATE TABLE blocklist ( id INTEGER NOT NULL, work_id INTEGER, foreign_id INTEGER, book_key VARCHAR(300) DEFAULT '' NOT NULL, kind VARCHAR(8) NOT NULL, title VARCHAR(400) NOT NULL, title_key VARCHAR(400) NOT NULL, protocol VARCHAR(8) NOT NULL, info_hash VARCHAR(40) DEFAULT '' NOT NULL, indexer_name VARCHAR(100) DEFAULT '' NOT NULL, reason VARCHAR(32) NOT NULL, by_user_id INTEGER, created_at DATETIME NOT NULL, library_id INTEGER, PRIMARY KEY (id), FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE SET NULL, FOREIGN KEY(foreign_id) REFERENCES foreign_books (id) ON DELETE SET NULL, FOREIGN KEY(by_user_id) REFERENCES users (id) ON DELETE SET NULL, FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE SET NULL );
CREATE VIRTUAL TABLE book_fts USING fts5(title, original, people, series, description, ids, tokenize = 'unicode61 remove_diacritics 2', content = '', contentless_delete = 1);
CREATE TABLE bookmarks ( id INTEGER NOT NULL, user_id INTEGER NOT NULL, edition_id INTEGER NOT NULL, locator VARCHAR(1000) NOT NULL, fraction FLOAT DEFAULT 0 NOT NULL, chapter_title VARCHAR(300) DEFAULT '' NOT NULL, created_at DATETIME NOT NULL, note VARCHAR(500) DEFAULT '' NOT NULL, PRIMARY KEY (id), UNIQUE (user_id, edition_id, locator), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE chapters ( id INTEGER NOT NULL, edition_id INTEGER NOT NULL, number INTEGER NOT NULL, title VARCHAR(300) NOT NULL, start_ms INTEGER DEFAULT 0 NOT NULL, target VARCHAR(500) DEFAULT '' NOT NULL, depth INTEGER DEFAULT 0 NOT NULL, PRIMARY KEY (id), FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE credits ( id INTEGER NOT NULL, person_id INTEGER NOT NULL, work_id INTEGER, edition_id INTEGER, role VARCHAR(12) NOT NULL, position INTEGER DEFAULT 0 NOT NULL, PRIMARY KEY (id), FOREIGN KEY(person_id) REFERENCES people (id) ON DELETE CASCADE, FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE devices ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, account_id INTEGER NOT NULL, name VARCHAR(80) NOT NULL, token_hash VARCHAR(64) NOT NULL, prefix VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, revoked_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE download_clients ( id INTEGER NOT NULL, name VARCHAR(100) NOT NULL, kind VARCHAR(16) NOT NULL, url VARCHAR(1024) NOT NULL, username VARCHAR(256) DEFAULT '' NOT NULL, secret_enc TEXT DEFAULT '' NOT NULL, category VARCHAR(64) DEFAULT 'nexbooks' NOT NULL, priority INTEGER DEFAULT 1 NOT NULL, enabled BOOLEAN DEFAULT 1 NOT NULL, version VARCHAR(40) DEFAULT '' NOT NULL, last_error VARCHAR(64) DEFAULT '' NOT NULL, checked_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id) );
CREATE TABLE downloads ( id INTEGER NOT NULL, user_id INTEGER, work_id INTEGER, foreign_id INTEGER, library_id INTEGER, kind VARCHAR(8) NOT NULL, language VARCHAR(8) DEFAULT '' NOT NULL, title VARCHAR(400) NOT NULL, format VARCHAR(12) DEFAULT '' NOT NULL, size BIGINT, protocol VARCHAR(8) NOT NULL, info_hash VARCHAR(40) DEFAULT '' NOT NULL, indexer_id INTEGER, indexer_name VARCHAR(100) DEFAULT '' NOT NULL, client_id INTEGER, client_name VARCHAR(100) DEFAULT '' NOT NULL, client_ref VARCHAR(128) DEFAULT '' NOT NULL, category VARCHAR(64) DEFAULT '' NOT NULL, state VARCHAR(16) NOT NULL, forced JSON, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, wish_id INTEGER, progress FLOAT, remaining_seconds INTEGER, client_state VARCHAR(64) DEFAULT '' NOT NULL, problem_code VARCHAR(32) DEFAULT '' NOT NULL, problem_values JSON, reported_path VARCHAR(4096) DEFAULT '' NOT NULL, missing_count INTEGER DEFAULT 0 NOT NULL, completed_at DATETIME, finished_at DATETIME, failed_reason VARCHAR(32) DEFAULT '' NOT NULL, failed_detail VARCHAR(32) DEFAULT '' NOT NULL, removal_pending BOOLEAN DEFAULT 0 NOT NULL, goal_ratio FLOAT, goal_seconds INTEGER, imported_at DATETIME, seed_state VARCHAR(10) DEFAULT '' NOT NULL, seed_ratio FLOAT, seed_seconds INTEGER, place_step VARCHAR(10) DEFAULT '' NOT NULL, source_path VARCHAR(4096) DEFAULT '' NOT NULL, decision JSON, edition_id INTEGER, replaced JSON, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL, FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE SET NULL, FOREIGN KEY(foreign_id) REFERENCES foreign_books (id) ON DELETE SET NULL, FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE SET NULL, FOREIGN KEY(indexer_id) REFERENCES indexers (id) ON DELETE SET NULL, FOREIGN KEY(client_id) REFERENCES download_clients (id) ON DELETE SET NULL, FOREIGN KEY(wish_id) REFERENCES procure_wishes (id) ON DELETE SET NULL, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE SET NULL );
CREATE TABLE edition_moves ( old_id INTEGER NOT NULL, new_id INTEGER NOT NULL, shift_ms INTEGER DEFAULT 0 NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (old_id), FOREIGN KEY(new_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE editions ( id INTEGER NOT NULL, work_id INTEGER NOT NULL, library_id INTEGER NOT NULL, kind VARCHAR(8) NOT NULL, variant VARCHAR(12) DEFAULT '' NOT NULL, variant_uncertain BOOLEAN DEFAULT 0 NOT NULL, language VARCHAR(8) DEFAULT '' NOT NULL, title VARCHAR(300) NOT NULL, subtitle VARCHAR(300) DEFAULT '' NOT NULL, isbn VARCHAR(20) DEFAULT '' NOT NULL, asin VARCHAR(20) DEFAULT '' NOT NULL, publisher VARCHAR(200) DEFAULT '' NOT NULL, published VARCHAR(10) DEFAULT '' NOT NULL, description TEXT DEFAULT '' NOT NULL, genre VARCHAR(16) DEFAULT '' NOT NULL, series_name VARCHAR(200) DEFAULT '' NOT NULL, series_id INTEGER, series_pos FLOAT, original_title VARCHAR(300) DEFAULT '' NOT NULL, title_key VARCHAR(300) DEFAULT '' NOT NULL, shelf_key VARCHAR(500) DEFAULT '' NOT NULL, pages INTEGER DEFAULT 0 NOT NULL, duration INTEGER DEFAULT 0 NOT NULL, cover VARCHAR(64) DEFAULT '' NOT NULL, color VARCHAR(7) DEFAULT '' NOT NULL, missing_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, original_language VARCHAR(8) DEFAULT '' NOT NULL, overlay JSON, grouped_by VARCHAR(8) DEFAULT '' NOT NULL, genre_guess BOOLEAN DEFAULT 0 NOT NULL, PRIMARY KEY (id), FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE CASCADE, FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE, FOREIGN KEY(series_id) REFERENCES series (id) ON DELETE SET NULL );
CREATE TABLE email_confirmations ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, address VARCHAR(255) NOT NULL, token_hash VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (account_id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash) );
CREATE TABLE external_refs ( id INTEGER NOT NULL, work_id INTEGER, edition_id INTEGER, source VARCHAR(16) NOT NULL, kind VARCHAR(8) NOT NULL, "key" VARCHAR(120) NOT NULL, market VARCHAR(8) DEFAULT '' NOT NULL, PRIMARY KEY (id), UNIQUE (edition_id, source, kind, "key", market), FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE files ( id INTEGER NOT NULL, library_id INTEGER NOT NULL, edition_id INTEGER, role VARCHAR(8) NOT NULL, path VARCHAR(1500) NOT NULL, size BIGINT NOT NULL, mtime_ns BIGINT NOT NULL, sha256 VARCHAR(64) DEFAULT '' NOT NULL, format VARCHAR(8) NOT NULL, part INTEGER DEFAULT 1 NOT NULL, duration_ms INTEGER DEFAULT 0 NOT NULL, unit VARCHAR(1500) DEFAULT '' NOT NULL, probe JSON, dirty BOOLEAN DEFAULT 0 NOT NULL, missing_at DATETIME, seen_at DATETIME NOT NULL, created_at DATETIME NOT NULL, rev INTEGER DEFAULT 0 NOT NULL, PRIMARY KEY (id), UNIQUE (library_id, path), FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE foreign_books ( id INTEGER NOT NULL, token VARCHAR(24) NOT NULL, ref VARCHAR(80) NOT NULL, title VARCHAR(300) NOT NULL, title_key VARCHAR(300) DEFAULT '' NOT NULL, authors JSON, released VARCHAR(10) DEFAULT '' NOT NULL, language VARCHAR(8) DEFAULT '' NOT NULL, genre VARCHAR(16) DEFAULT '' NOT NULL, series VARCHAR(200) DEFAULT '' NOT NULL, series_pos FLOAT, cover_url VARCHAR(500) DEFAULT '' NOT NULL, cover VARCHAR(64) DEFAULT '' NOT NULL, color VARCHAR(7) DEFAULT '' NOT NULL, data JSON, enriched_at DATETIME, seen_at DATETIME NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (token), UNIQUE (ref) );
CREATE TABLE foreign_jobs ( id INTEGER NOT NULL, client_id INTEGER NOT NULL, ref VARCHAR(128) NOT NULL, name VARCHAR(400) NOT NULL, job_state VARCHAR(12) DEFAULT '' NOT NULL, ignored BOOLEAN DEFAULT 0 NOT NULL, first_seen_at DATETIME NOT NULL, last_seen_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (client_id, ref), FOREIGN KEY(client_id) REFERENCES download_clients (id) ON DELETE CASCADE );
CREATE TABLE history ( id INTEGER NOT NULL, user_id INTEGER NOT NULL, edition_id INTEGER NOT NULL, kind VARCHAR(8) NOT NULL, finished_on VARCHAR(10) NOT NULL, source VARCHAR(4) DEFAULT 'hand' NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (user_id, edition_id, finished_on), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE indexers ( id INTEGER NOT NULL, name VARCHAR(100) NOT NULL, kind VARCHAR(8) NOT NULL, url VARCHAR(1024) NOT NULL, api_key_enc TEXT DEFAULT '' NOT NULL, enabled BOOLEAN DEFAULT 1 NOT NULL, priority INTEGER DEFAULT 25 NOT NULL, daily_limit INTEGER DEFAULT 0 NOT NULL, categories JSON, category_langs JSON, caps JSON, caps_checked_at DATETIME, paused_until DATETIME, pause_cause VARCHAR(32) DEFAULT '' NOT NULL, last_error VARCHAR(64) DEFAULT '' NOT NULL, api_current INTEGER, api_max INTEGER, grab_current INTEGER, grab_max INTEGER, limits_seen_at DATETIME, used_day VARCHAR(10) DEFAULT '' NOT NULL, used_count INTEGER DEFAULT 0 NOT NULL, grabs INTEGER DEFAULT 0 NOT NULL, prowlarr_indexer_id INTEGER, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, grab_day VARCHAR(10) DEFAULT '' NOT NULL, grab_count INTEGER DEFAULT 0 NOT NULL, rss_checked_at DATETIME, rss_error VARCHAR(64) DEFAULT '' NOT NULL, grab_paused_until DATETIME, PRIMARY KEY (id) );
CREATE TABLE invites ( id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, email VARCHAR(255) NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (token_hash), FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE jobs ( id INTEGER NOT NULL, kind VARCHAR(16) NOT NULL, ref INTEGER NOT NULL, payload JSON, state VARCHAR(8) NOT NULL, attempts INTEGER NOT NULL, created_at DATETIME NOT NULL, started_at DATETIME, finished_at DATETIME, error VARCHAR(300) DEFAULT '' NOT NULL, PRIMARY KEY (id) );
CREATE TABLE libraries ( id INTEGER NOT NULL, name VARCHAR(80) NOT NULL, path VARCHAR(1000) NOT NULL, kind VARCHAR(8) NOT NULL, scan_enabled BOOLEAN DEFAULT 1 NOT NULL, scanned_at DATETIME, retry_at DATETIME, progress_done INTEGER DEFAULT 0 NOT NULL, progress_total INTEGER DEFAULT 0 NOT NULL, report JSON, created_at DATETIME NOT NULL, rev INTEGER DEFAULT 0 NOT NULL, reread_rev INTEGER DEFAULT 0 NOT NULL, PRIMARY KEY (id), UNIQUE (name), UNIQUE (path) );
CREATE TABLE library_members ( id INTEGER NOT NULL, library_id INTEGER NOT NULL, user_id INTEGER NOT NULL, "right" VARCHAR(8) NOT NULL, PRIMARY KEY (id), UNIQUE (library_id, user_id), FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE library_problems ( id INTEGER NOT NULL, library_id INTEGER NOT NULL, path VARCHAR(1500) NOT NULL, reason VARCHAR(32) NOT NULL, size BIGINT NOT NULL, mtime_ns BIGINT NOT NULL, seen_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (library_id, path), FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE );
CREATE TABLE list_fetches ( source VARCHAR(16) NOT NULL, market VARCHAR(8) NOT NULL, unit VARCHAR(10) NOT NULL, fetched_at DATETIME, state VARCHAR(8) DEFAULT '' NOT NULL, count INTEGER DEFAULT 0 NOT NULL, error VARCHAR(40) DEFAULT '' NOT NULL, wanted_at DATETIME, PRIMARY KEY (source, market, unit) );
CREATE TABLE lists_cache ( id INTEGER NOT NULL, source VARCHAR(16) NOT NULL, market VARCHAR(8) DEFAULT '' NOT NULL, list VARCHAR(10) NOT NULL, rank INTEGER NOT NULL, ref VARCHAR(80) NOT NULL, foreign_id INTEGER NOT NULL, title VARCHAR(300) NOT NULL, author VARCHAR(300) DEFAULT '' NOT NULL, cover_url VARCHAR(500) DEFAULT '' NOT NULL, released VARCHAR(10) DEFAULT '' NOT NULL, kind VARCHAR(8) DEFAULT 'ebook' NOT NULL, language VARCHAR(8) DEFAULT '' NOT NULL, genre VARCHAR(16) DEFAULT '' NOT NULL, fetched_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (source, market, list, rank), FOREIGN KEY(foreign_id) REFERENCES foreign_books (id) ON DELETE CASCADE );
CREATE TABLE match_queue ( id INTEGER NOT NULL, library_id INTEGER NOT NULL, edition_id INTEGER NOT NULL, state VARCHAR(8) NOT NULL, reason VARCHAR(40) DEFAULT '' NOT NULL, proposals JSON, fingerprint VARCHAR(64) DEFAULT '' NOT NULL, decision VARCHAR(10) DEFAULT '' NOT NULL, decided_by INTEGER, decided_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (edition_id), FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE, FOREIGN KEY(decided_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE oidc_links ( id INTEGER NOT NULL, provider_id INTEGER NOT NULL, subject VARCHAR(255) NOT NULL, account_id INTEGER NOT NULL, issuer VARCHAR(500) NOT NULL, email VARCHAR(320), created_at DATETIME NOT NULL, last_used_at DATETIME, PRIMARY KEY (id), UNIQUE (provider_id, subject), UNIQUE (provider_id, account_id), FOREIGN KEY(provider_id) REFERENCES oidc_providers (id) ON DELETE CASCADE, FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE oidc_providers ( id INTEGER NOT NULL, slug VARCHAR(40) NOT NULL, label VARCHAR(64) NOT NULL, issuer VARCHAR(500) NOT NULL, client_id VARCHAR(255) NOT NULL, client_secret_enc TEXT NOT NULL, scopes VARCHAR(500) NOT NULL, enabled BOOLEAN NOT NULL, auto_create BOOLEAN NOT NULL, trusts_second_factor BOOLEAN NOT NULL, managed VARCHAR(20) NOT NULL, position INTEGER NOT NULL, redirect_path VARCHAR(300) NOT NULL, registered_redirect VARCHAR(500) DEFAULT '' NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (slug) );
CREATE TABLE organize_moves ( id INTEGER NOT NULL, run_id INTEGER NOT NULL, file_id INTEGER, edition_id INTEGER, source VARCHAR(1500) NOT NULL, target VARCHAR(1500) NOT NULL, state VARCHAR(8) NOT NULL, reason VARCHAR(32) DEFAULT '' NOT NULL, size BIGINT NOT NULL, mtime_ns BIGINT NOT NULL, PRIMARY KEY (id), FOREIGN KEY(run_id) REFERENCES organize_runs (id) ON DELETE CASCADE, FOREIGN KEY(file_id) REFERENCES files (id) ON DELETE SET NULL, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE SET NULL );
CREATE TABLE organize_runs ( id INTEGER NOT NULL, library_id INTEGER NOT NULL, created_by INTEGER, scheme VARCHAR(300) NOT NULL, state VARCHAR(8) NOT NULL, summary JSON, done INTEGER DEFAULT 0 NOT NULL, total INTEGER DEFAULT 0 NOT NULL, error VARCHAR(40) DEFAULT '' NOT NULL, created_at DATETIME NOT NULL, started_at DATETIME, finished_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE passkeys ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, user_id INTEGER NOT NULL, credential_id BLOB NOT NULL, public_key BLOB NOT NULL, sign_count INTEGER NOT NULL, name VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE password_resets ( id INTEGER NOT NULL, account_id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL, created_by INTEGER, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(account_id) REFERENCES users (id) ON DELETE CASCADE, UNIQUE (token_hash), FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL );
CREATE TABLE path_mappings ( id INTEGER NOT NULL, client_id INTEGER NOT NULL, remote VARCHAR(1000) NOT NULL, local VARCHAR(1000) NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(client_id) REFERENCES download_clients (id) ON DELETE CASCADE );
CREATE TABLE people ( id INTEGER NOT NULL, name VARCHAR(200) NOT NULL, sort_name VARCHAR(200) NOT NULL, "key" VARCHAR(200) NOT NULL, PRIMARY KEY (id), UNIQUE ("key") );
CREATE TABLE person_aliases ( id INTEGER NOT NULL, person_id INTEGER NOT NULL, name VARCHAR(200) NOT NULL, "key" VARCHAR(200) NOT NULL, source VARCHAR(16) DEFAULT '' NOT NULL, created_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(person_id) REFERENCES people (id) ON DELETE CASCADE, UNIQUE ("key") );
CREATE TABLE person_info ( person_id INTEGER NOT NULL, wikidata_id VARCHAR(16) DEFAULT '' NOT NULL, wikidata_state VARCHAR(8) DEFAULT '' NOT NULL, photo VARCHAR(64) DEFAULT '' NOT NULL, photo_source VARCHAR(16) DEFAULT '' NOT NULL, photo_author VARCHAR(200) DEFAULT '' NOT NULL, photo_license VARCHAR(80) DEFAULT '' NOT NULL, photo_license_url VARCHAR(300) DEFAULT '' NOT NULL, photo_page VARCHAR(300) DEFAULT '' NOT NULL, bios JSON, checked_at DATETIME, name_key VARCHAR(200) DEFAULT '' NOT NULL, PRIMARY KEY (person_id), FOREIGN KEY(person_id) REFERENCES people (id) ON DELETE CASCADE );
CREATE TABLE person_photos ( person_id INTEGER NOT NULL, library_id INTEGER NOT NULL, photo VARCHAR(64) NOT NULL, path VARCHAR(1500) NOT NULL, size BIGINT NOT NULL, mtime_ns BIGINT NOT NULL, PRIMARY KEY (person_id, library_id), FOREIGN KEY(person_id) REFERENCES people (id) ON DELETE CASCADE, FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE );
CREATE TABLE procure_files ( id INTEGER NOT NULL, download_id INTEGER NOT NULL, path VARCHAR(1500) NOT NULL, origin VARCHAR(8) DEFAULT 'source' NOT NULL, size BIGINT NOT NULL, format VARCHAR(8) NOT NULL, role VARCHAR(8) NOT NULL, unit VARCHAR(1500) DEFAULT '' NOT NULL, probe JSON, state VARCHAR(8) NOT NULL, reason VARCHAR(32) DEFAULT '' NOT NULL, target VARCHAR(1500) DEFAULT '' NOT NULL, how VARCHAR(8) DEFAULT '' NOT NULL, wish_id INTEGER, mtime_ns BIGINT DEFAULT 0 NOT NULL, sha256 VARCHAR(64) DEFAULT '' NOT NULL, PRIMARY KEY (id), FOREIGN KEY(download_id) REFERENCES downloads (id) ON DELETE CASCADE, FOREIGN KEY(wish_id) REFERENCES procure_wishes (id) ON DELETE SET NULL );
CREATE TABLE procure_history ( id INTEGER NOT NULL, user_id INTEGER, library_id INTEGER, work_id INTEGER, foreign_id INTEGER, kind VARCHAR(8) NOT NULL, book_title VARCHAR(300) DEFAULT '' NOT NULL, book_author VARCHAR(300) DEFAULT '' NOT NULL, release VARCHAR(400) DEFAULT '' NOT NULL, indexer_name VARCHAR(100) DEFAULT '' NOT NULL, result VARCHAR(10) NOT NULL, note JSON, created_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL, FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE SET NULL, FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE SET NULL, FOREIGN KEY(foreign_id) REFERENCES foreign_books (id) ON DELETE SET NULL );
CREATE TABLE procure_notices ( id INTEGER NOT NULL, user_id INTEGER NOT NULL, edition_id INTEGER, download_id INTEGER, trash_id INTEGER, code VARCHAR(32) NOT NULL, detail JSON, created_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE, FOREIGN KEY(download_id) REFERENCES downloads (id) ON DELETE SET NULL, FOREIGN KEY(trash_id) REFERENCES trash_entries (id) ON DELETE SET NULL );
CREATE TABLE procure_wishes ( id INTEGER NOT NULL, user_id INTEGER NOT NULL, work_id INTEGER, foreign_id INTEGER, kind VARCHAR(8) NOT NULL, language VARCHAR(8) DEFAULT '' NOT NULL, library_id INTEGER, state VARCHAR(12) NOT NULL, search_id INTEGER, searched_at DATETIME, next_try_at DATETIME, detail JSON, release_date VARCHAR(10) DEFAULT '' NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, done_at DATETIME, handover JSON, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE CASCADE, FOREIGN KEY(foreign_id) REFERENCES foreign_books (id) ON DELETE CASCADE, FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE SET NULL );
CREATE TABLE progress ( user_id INTEGER NOT NULL, edition_id INTEGER NOT NULL, locator VARCHAR(1000) NOT NULL, fraction FLOAT DEFAULT 0 NOT NULL, unit VARCHAR(8) DEFAULT 'chapter' NOT NULL, chapter INTEGER DEFAULT 0 NOT NULL, chapter_count INTEGER DEFAULT 0 NOT NULL, chapter_title VARCHAR(300) DEFAULT '' NOT NULL, device_key VARCHAR(40) DEFAULT '' NOT NULL, device VARCHAR(80) DEFAULT '' NOT NULL, moved_at DATETIME NOT NULL, received_at DATETIME NOT NULL, pass_done BOOLEAN DEFAULT 0 NOT NULL, PRIMARY KEY (user_id, edition_id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE prowlarr_connections ( id INTEGER NOT NULL, url VARCHAR(1024) NOT NULL, api_key_enc TEXT DEFAULT '' NOT NULL, auto_add BOOLEAN DEFAULT 1 NOT NULL, version VARCHAR(40) DEFAULT '' NOT NULL, last_sync_at DATETIME, last_error VARCHAR(64) DEFAULT '' NOT NULL, last_counts JSON, created_at DATETIME NOT NULL, PRIMARY KEY (id) );
CREATE TABLE push_devices ( id INTEGER NOT NULL, uid VARCHAR(32) NOT NULL, user_id INTEGER NOT NULL, endpoint_key VARCHAR(64) NOT NULL, content TEXT NOT NULL, created_at DATETIME NOT NULL, last_used_at DATETIME, PRIMARY KEY (id), CONSTRAINT uq_push_devices_uid UNIQUE (uid), CONSTRAINT uq_push_devices_user_endpoint UNIQUE (user_id, endpoint_key), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE );
CREATE TABLE release_searches ( id INTEGER NOT NULL, user_id INTEGER NOT NULL, work_id INTEGER, foreign_id INTEGER, language VARCHAR(8) NOT NULL, subject JSON, state VARCHAR(8) NOT NULL, progress JSON, error VARCHAR(64) DEFAULT '' NOT NULL, created_at DATETIME NOT NULL, started_at DATETIME, finished_at DATETIME, origin VARCHAR(8) DEFAULT 'search' NOT NULL, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE CASCADE, FOREIGN KEY(foreign_id) REFERENCES foreign_books (id) ON DELETE CASCADE );
CREATE TABLE rss_seen ( indexer_id INTEGER NOT NULL, "key" VARCHAR(32) NOT NULL, seen_at DATETIME NOT NULL, PRIMARY KEY (indexer_id, "key"), FOREIGN KEY(indexer_id) REFERENCES indexers (id) ON DELETE CASCADE );
CREATE TABLE search_entries ( edition_id INTEGER NOT NULL, digest VARCHAR(40) NOT NULL, PRIMARY KEY (edition_id), FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE CASCADE );
CREATE TABLE search_releases ( id INTEGER NOT NULL, search_id INTEGER NOT NULL, indexer_id INTEGER, indexer_name VARCHAR(100) DEFAULT '' NOT NULL, protocol VARCHAR(8) NOT NULL, title VARCHAR(400) NOT NULL, size BIGINT, published_at DATETIME, seeders INTEGER, peers INTEGER, grabs INTEGER, categories JSON, guid VARCHAR(24) DEFAULT '' NOT NULL, info_hash VARCHAR(40) DEFAULT '' NOT NULL, link_enc TEXT DEFAULT '' NOT NULL, min_ratio FLOAT, min_seed_seconds INTEGER, kind VARCHAR(8) NOT NULL, format VARCHAR(12) DEFAULT '' NOT NULL, format_how VARCHAR(10) DEFAULT '' NOT NULL, tier INTEGER DEFAULT 0 NOT NULL, language VARCHAR(8) DEFAULT '' NOT NULL, language_how VARCHAR(10) DEFAULT '' NOT NULL, variant VARCHAR(12) DEFAULT '' NOT NULL, bitrate INTEGER, reasons JSON, score INTEGER DEFAULT 0 NOT NULL, rank INTEGER, PRIMARY KEY (id), FOREIGN KEY(search_id) REFERENCES release_searches (id) ON DELETE CASCADE, FOREIGN KEY(indexer_id) REFERENCES indexers (id) ON DELETE SET NULL );
CREATE TABLE series ( id INTEGER NOT NULL, name VARCHAR(200) NOT NULL, "key" VARCHAR(200) NOT NULL, PRIMARY KEY (id), UNIQUE ("key") );
CREATE TABLE settings ( "key" VARCHAR(64) NOT NULL, value JSON, PRIMARY KEY ("key") );
CREATE TABLE source_cache ( id INTEGER NOT NULL, source VARCHAR(16) NOT NULL, "key" VARCHAR(300) NOT NULL, value JSON, fetched_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (source, "key") );
CREATE TABLE source_state ( source VARCHAR(16) NOT NULL, tokens FLOAT DEFAULT 0 NOT NULL, refilled_at DATETIME, day VARCHAR(10) DEFAULT '' NOT NULL, day_count INTEGER DEFAULT 0 NOT NULL, last_ok_at DATETIME, last_error VARCHAR(40) DEFAULT '' NOT NULL, last_error_at DATETIME, fail_count INTEGER DEFAULT 0 NOT NULL, blocked_until DATETIME, state VARCHAR(16) DEFAULT '' NOT NULL, PRIMARY KEY (source) );
CREATE TABLE trash_entries ( id INTEGER NOT NULL, library_id INTEGER NOT NULL, work_id INTEGER, edition_id INTEGER, kind VARCHAR(8) NOT NULL, title VARCHAR(300) DEFAULT '' NOT NULL, author VARCHAR(300) DEFAULT '' NOT NULL, format VARCHAR(12) DEFAULT '' NOT NULL, files JSON, folder VARCHAR(64) NOT NULL, size BIGINT NOT NULL, download_id INTEGER, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(library_id) REFERENCES libraries (id) ON DELETE CASCADE, FOREIGN KEY(work_id) REFERENCES works (id) ON DELETE SET NULL, FOREIGN KEY(edition_id) REFERENCES editions (id) ON DELETE SET NULL, FOREIGN KEY(download_id) REFERENCES downloads (id) ON DELETE SET NULL );
CREATE TABLE users ( id INTEGER NOT NULL, name VARCHAR(64) NOT NULL, display_name VARCHAR(80) NOT NULL, whats_new_seen VARCHAR(32) NOT NULL, role VARCHAR(16) NOT NULL, sign_in VARCHAR(16) NOT NULL, password_hash VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, email_confirmed_at DATETIME, email_from_provider BOOLEAN DEFAULT 0 NOT NULL, language VARCHAR(16) NOT NULL, profile JSON, created_at DATETIME NOT NULL, last_seen_at DATETIME, failed_logins INTEGER NOT NULL, locked_until DATETIME, blocked_at DATETIME, totp_secret_enc TEXT NOT NULL, totp_recovery TEXT NOT NULL, totp_last_step INTEGER NOT NULL, avatar BLOB, avatar_at DATETIME, signed_in_before BOOLEAN DEFAULT 0 NOT NULL, passkey_handle VARCHAR(64) DEFAULT '' NOT NULL, PRIMARY KEY (id), UNIQUE (name) );
CREATE TABLE wishlist ( id INTEGER NOT NULL, user_id INTEGER NOT NULL, foreign_id INTEGER NOT NULL, title VARCHAR(300) NOT NULL, author VARCHAR(300) DEFAULT '' NOT NULL, cover VARCHAR(64) DEFAULT '' NOT NULL, added_at DATETIME NOT NULL, PRIMARY KEY (id), UNIQUE (user_id, foreign_id), FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, FOREIGN KEY(foreign_id) REFERENCES foreign_books (id) ON DELETE CASCADE );
CREATE TABLE works ( id INTEGER NOT NULL, title VARCHAR(300) NOT NULL, original_title VARCHAR(300) DEFAULT '' NOT NULL, original_language VARCHAR(8) DEFAULT '' NOT NULL, description TEXT DEFAULT '' NOT NULL, year INTEGER, genre VARCHAR(16) DEFAULT '' NOT NULL, color VARCHAR(7) DEFAULT '' NOT NULL, cover VARCHAR(64) DEFAULT '' NOT NULL, series_id INTEGER, series_pos FLOAT, pages INTEGER DEFAULT 0 NOT NULL, pattern INTEGER DEFAULT 0 NOT NULL, tall FLOAT DEFAULT (0.5) NOT NULL, gold BOOLEAN DEFAULT 0 NOT NULL, "key" VARCHAR(300) DEFAULT '' NOT NULL, main_key VARCHAR(300) DEFAULT '' NOT NULL, original_key VARCHAR(300) DEFAULT '' NOT NULL, added_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id), FOREIGN KEY(series_id) REFERENCES series (id) ON DELETE SET NULL );
